sys_script_include.script:
// B.6 ITFCommitteeCalendar
//
// Script Include class body. Loaded via Now.include().
// Class.create pattern: do NOT import Glide APIs here — they are auto-available
// in the Script Include execution context.
//
// Returns the next Hiring Freeze Committee meeting date, honouring the
// submission cutoff. Used verbatim from §14 B.6.
//
// committee_weekday and committee_cutoff_days are BLOCKED (D-08: OPM has not
// supplied values), so both properties are intentionally empty. This class
// therefore fails loud by design — it logs via gs.error and returns '' rather
// than inventing a meeting date.
var ITFCommitteeCalendar = Class.create();
ITFCommitteeCalendar.prototype = {
    initialize: function () {},

    nextMeetingDate: function () {
        var weekday = parseInt(gs.getProperty('x_snc_sas_positi_0.committee_weekday'), 10);
        var cutoff = parseInt(gs.getProperty('x_snc_sas_positi_0.committee_cutoff_days'), 10);
        if (isNaN(weekday) || isNaN(cutoff)) {
            gs.error('ITF: committee_weekday or committee_cutoff_days is not set');
            return '';
        }

        var d = new GlideDateTime();
        var delta = (weekday - d.getDayOfWeekLocalTime() + 7) % 7;
        while (delta < cutoff) {
            delta += 7;
        }
        d.addDaysLocalTime(delta);
        return d.getLocalDate().getValue();
    },

    type: 'ITFCommitteeCalendar',
};
